\label{Thm F}
    Let $k$ be a Noetherian ring.  Suppose that there is a morphism of $\mathrm{GL}_n$--algebras $f\colon B\to A$ such that both $B$ and $A$ are  finitely generated $k$--algebras,
         $B$ has a good filtration, and
         $f$ makes $A$ a Noetherian $B$--module.
     Then the following properties hold.
\begin{itemize}
    \item[$(a)$] $H^i(\mathrm{GL}_n,A)=0$ for $i$ large enough. 
    \item[$(b)$] $H^i(\mathrm{GL}_n,A)$ is a Noetherian $A^G$--module for every $i$.
\end{itemize}
In particular, this implies that $H^\ast(\mathrm{GL}_n,A)$ is a finitely generated $k$--algebra.

    An \textit{associative unital $k$--algebra $A$} is an associative and unital monoid object $(A,m,\eta)$ in $\textbf{Mod}_k$. Explicitly, $(A,m,\eta)$ consist of  a $k$--module $A$ together with a \textit{multiplication} $m\colon A\otimes A\to A$ and a \textit{unit map} $\eta\colon k\to A$, both $k$--linear,  satisfying the \textit{associative axiom} $m\circ (m\otimes\mathrm{id}_A)=m\circ(\mathrm{id}_A\otimes m)$ and \textit{right and left unital axioms} $m\circ (\eta \otimes \mathrm{id}_A)=\mathrm{id}_A=m\circ(\mathrm{id}_A\otimes \eta)$ which amounts to the commutativity of the following diagrams 
     \begin{center}
        \begin{tikzcd}
            &A\otimes A\otimes A \arrow[r, "m\otimes \mathrm{id}_A"]\arrow[d, "\mathrm{id}_A\otimes m"']&A\otimes A\arrow[d, "m"] &A\otimes k \arrow[d, "\mathrm{id}_A\otimes \eta"']\arrow[r, "\eta\otimes\mathrm{id}_A"] \arrow[dr, equals]&A\otimes A \arrow[d, "m"] \\
            &A\otimes A \arrow[r, "m"']&A &A\otimes A \arrow[r, "m"'] &A. 
        \end{tikzcd}
    \end{center}
Moreover, we say that $A$ is \textit{commutative} if the following diagram is commutative
\begin{center}
        \begin{tikzcd}
            A\otimes A \arrow[rr,"(12)"] \arrow[rd,"m"'] & & A\otimes A \arrow[dl,"m"]\\ & A &
        \end{tikzcd}
    \end{center}
    where $(12)$ means swapping the factors, that is, $(12)(a\otimes a')=a'\otimes a$.

An \textit{associative unital $k$--coalgebra $C$} is an associative unital monoid $(C,\Delta, \epsilon)$ in the category $\textbf{Mod}_k^\textrm{op}$. Unpacking the definition, the monoid $(C,\Delta,\epsilon)$ consists of a $k$--module $C$ together with two linear maps $\Delta\colon C\to C\otimes C$ and $C\to k$ called the \textit{comultiplication} and \textit{counit}, respectively, making the following diagrams commutative 

    \begin{center}
    \begin{tikzcd}
        &C \arrow[d, "\Delta"']\arrow[r, "\Delta"]&C\otimes C\arrow[d, "\Delta\otimes \mathrm{id}_C"] &C \arrow[d, "\Delta"']\arrow[r, "\Delta"] \arrow[dr, equals]&C\otimes C \arrow[d, "\mathrm{id}_C\otimes \varepsilon"] \\
        &C\otimes C \arrow[r, "\mathrm{id}_C \otimes \Delta"']&C\otimes C \otimes C &C\otimes C \arrow[r, "\varepsilon \otimes \mathrm{id}_C"'] &C\otimes k. 
    \end{tikzcd}
\end{center}
In this case, we refer to the left square as  the  \textit{coassociative axiom}  and to the right diagrams as the  \textit{right and left counital axioms}. We say that an associative unital $k$--algebra $C$ is \textit{cocommutative} if the following diagram is commutative 
\begin{center}
    \begin{tikzcd}
       & C \arrow[ld,"\Delta"'] \arrow[rd,"\Delta"] & \\ C\otimes C \arrow[rr,"(12)"']  & & C\otimes C.
    \end{tikzcd}
\end{center}

Let $(C_1,\Delta_1,\varepsilon_1)$ and $(C_2,\Delta_2,\varepsilon_2)$ be $k$--coalgebras. A \textit{a morphism of coalgebras from $C_1$ to $C_2$} is a $k$--linear map $f\colon C_1\to C_2$ such that the following diagrams are commutative 
\begin{center}
    \begin{tikzcd}
       C_1 \arrow[r,"f"] \arrow [d,"\Delta_1"'] & C_2 \arrow[d,"\Delta_2"] & C_1\arrow[r,"f"] \arrow[rd,"\varepsilon_1"'] & C_2 \arrow[d,"\varepsilon_2"] \\
       C_1\otimes C_1 \arrow[r,"f\otimes f"'] & C_2\otimes C_2 &  & k.
    \end{tikzcd}
\end{center}
A morphism $f\colon A_1\to A_2$ of algebras is defined in a similar fashion.

We only need to verify that for a morphism $f\colon C_1\to C_2$ of coalgebras, the map 
\[
f^\ast:=\mathrm{Hom}(f,A)\colon \mathrm{Hom}(C_2,A)\to \mathrm{Hom}(C_1,A)
\]
is a morphisms of algebras. Let $g,g'\in \mathrm{Hom}(C_2,A)$. We have the following commutative diagram 
 \begin{center}
    \begin{tikzcd}
       C_1 \arrow[r,"f"] \arrow [d,"\Delta_1"'] & C_2 \arrow[d,"\Delta_2"] \arrow[r,"\Delta_2"] & C_2\otimes C_2 \arrow[r,"g\otimes g'"] \arrow[d,equal] & A\otimes A \arrow[r] \arrow[d,equal] & A \arrow[d,equal] \\
       C_1\otimes C_1 \arrow[r,"f\otimes f"'] & C_2\otimes C_2 \arrow[r,equal] & C_2\otimes C_2 \arrow[r,"g\otimes g'"'] & A\otimes A \arrow[r] & A
    \end{tikzcd}
\end{center}
It follows that $f^\ast(g\ast g')=f^\ast(g)\ast f^\ast(g')$. The rest is easy.

    Let $(C, \Delta, \varepsilon)$ be a $k$--coalgebra. A \textit{(right) $C$--comodule} is a $k$--module $V$ equipped with a $k$--linear map $\Delta_V\colon  V\to V\otimes_k C$ called the \textit{coaction}, such that the following diagrams commute:
    \begin{center}
        \begin{tikzcd}
            &V \arrow[d, "\Delta_V"']\arrow[r, "\Delta_V"]&V\otimes C\arrow[d, "\Delta_V\otimes \mathrm{id}_C"] &V \arrow[r, "\Delta_V"] \arrow[dr, equals]&V\otimes C \arrow[d, "\mathrm{id}_V\otimes \varepsilon"] \\
            &V\otimes C \arrow[r, "\mathrm{id}_V \otimes \Delta"']&V\otimes C \otimes C & &V\otimes k. 
        \end{tikzcd}
    \end{center}

    Let $(W, \Delta_W)$ be another $C$--comodule, a $k$--linear map $f\colon V\to W$ is called a $C$-\textit{comodule homomorphism} if the following diagram commutes:
    \begin{center}
        \begin{tikzcd}
            &V \arrow[r, "\Delta_V"]\arrow[d, "f"']&V\otimes C \arrow[d, "f\otimes \mathrm{id}_C"] \\
            &W\arrow[r, "\Delta_W"'] &W\otimes C .
        \end{tikzcd}
    \end{center}

We will denote the set of $C$--comodule homomorphisms from $(V, \Delta_V)$ to $(W, \Delta_W)$ by $\mathrm{Hom}^C(V, W)$. Furthermore, we will denote the category of $C$--comodules and $C$--comodule homomorphisms by $\textbf{coMod}_C$. In a similar way, one defines the category of left $C$--comodules and homomorphisms, it will be denoted by  ${}_{C}\textbf{coMod}$. 

Furthermore, let $(V, \Delta_V)$ be any $C$--comodule. If $W\subseteq V$ is a $k$--submodule of $V$, we will say that it is a \textit{subcomodule} if the inclusion map is a $C$--comodule homomorphism.

\label{injectives}
    Let $C$ be a $k$--coalgebra which is flat as a $k$--module. Then the following properties hold. 
    \begin{enumerate}[(i)]
        \item If $J$ is an injective $k$--module, then $(J\otimes_k C, \mathrm{id}_J\otimes \Delta)$ is an injective $C$--comodule.
        \item The category \emph{\textbf{coMod}}$_C$ has enough injectives.
    \end{enumerate}

\label{projectives are injectives}
In many cases of interest, the category $\mathbf{coMod}_C$ also has enough projectives. Generally, projective and injective objects are quite distinct; however, when the coalgebra $C$ is finitely generated and projective over $k$, a strong relationship between projective and injective objects emerges provided that $C$ possesses additional structure as a \textit{commutative Hopf algebra}. In this case, it has been shown in \cite{Par71} that $C^\ast$ forms a \textit{quasi-Frobenius algebra} over $k$, as defined in \cite{Mul64}. Consequently, the regular representation $C^\ast$ is injective. Therefore, any $C^\ast$--module that is projective as a $k$--module is also injective as a $C^\ast$--module. For a detailed treatment when $k$ is a field, see \cite[Chapter 9]{DV94}.


A pertinent example is the group algebra $kG$, where $G$ is a finite group and $k$ is a field. In this case, $kG$ is indeed a Frobenius algebra, implying that $kG\cong (kG)^\ast$, and hence projective modules agree with injective modules.

    Let $k$ be a ring. A \textit{bialgebra} $B$ over $k$ is a $k$--module which is both a unital associative algebra and a counital coassociative coalgebra over $k$ in a compatible way. 

    To spell this out more precisely: 
    \begin{enumerate}[(i)]
        \item $B$ is equipped with a $k$--linear map $\nabla\colon B\otimes_k B\to B $ called the \textit{multiplication}, and a $k$--linear map $\eta\colon k\to B$ called the \textit{unit}, such that $(B, \nabla, \eta)$ is a unital associative $k$--algebra.
        \item $B$ is equipped with a $k$--linear map $\Delta\colon B\to B \otimes_k B$ called the \textit{comultiplication}, and a $k$--linear map $\varepsilon\colon B\to k$ called the \textit{counit}, such that $(B, \Delta, \varepsilon)$ is a counital coassociative $k$--coalgebra.
        \item These structures are compatible, that is, $\eta$ and $\nabla$ are morphisms of counital coalgebras, and $\varepsilon$ and $\Delta$ are a morphisms of unital algebras. In diagrammatic form this means that the following diagrams commute:
\begin{center}
    \begin{tikzcd}[column sep=small]
        &B\otimes B \arrow[dr, "\varepsilon\otimes \varepsilon"']\arrow[rr, "\nabla"]& &B\arrow[dl, "\varepsilon"] & &k \arrow[rr, "\mathrm{id}"]\arrow[dr, "\eta"']& &k &  &k\otimes k\simeq k \arrow[dr, "\eta"] \arrow[dl, "\eta\otimes\eta"'] &\\

        & &k\otimes k\simeq k & & & &B \arrow[ur, "\varepsilon"'] &   &B\otimes B & &B \arrow[ll, "\Delta"]
    \end{tikzcd}
\end{center}
\begin{center}
\begin{tikzcd}
    &B\otimes B \arrow[r, "\nabla"]\arrow[d, "\Delta\otimes\Delta"']&B\arrow[r, "\Delta"] &B\otimes B \\
    &B\otimes B\otimes B\otimes B \arrow[rr, "\mathrm{id}\otimes (12)\otimes \mathrm{id}"']& &B\otimes B\otimes B\otimes B \arrow[u, "\nabla\otimes\nabla"']
\end{tikzcd}
\end{center}
where $(12)(x\otimes y)=y\otimes x$ is the swapping morphism. A $k$--linear morphism between bialgebras is said to be a \textit{bialgebra homomorphism} if it is both a map of algebras and coalgebras.
    \end{enumerate}

From Remark \ref{dual of a coalgebra}, we can see that for any bialgebra $B$, we can always give $\mathrm{Hom}_k(B, B)$ the structure of a $k$--algebra via the convolution product. A \textit{Hopf algebra} is a bialgebra $H$ over $k$, equipped with a $k$--linear map $S\colon H\to H$ called the \textit{antipode} which is both a left and right convolution inverse to the identity map $\mathrm{id}_H\colon H\to H$ in $\mathrm{Hom}_k(H, H)$. In other words, $S$ makes the following diagram commute:
        \begin{center}
            \begin{tikzcd}[column sep=tiny]
                & &H\otimes H \arrow[rr, "S\otimes \mathrm{id}"]& &H\otimes H \arrow[ddr, "\nabla"] & \\
                & & & & & \\
                &H \arrow[ddr, "\Delta"']\arrow[uur, "\Delta"]\arrow[rr, "\varepsilon"]& &k \arrow[rr, "\eta"]& &H \\
                & & & & & \\
                & &H\otimes H \arrow[rr, "\mathrm{id} \otimes S"'] & &H\otimes H \arrow[uur, "\nabla"']& 
            \end{tikzcd}
        \end{center}
       A \textit{morphism of Hopf algebras} is just a morphism of bialgebras which commutes with the antipodes. In fact, any morphism of bialgebras will automatically respect the antipode (see Lemma \ref{bialgebra maps}). We will denote the category of Hopf algebras over $k$ by $\textbf{Hopf}_k$.

\label{Properties of the antipode}
